const raw = $input.first().json;
const body = raw.body || raw;

const evento = (body?.event || '').toLowerCase();
const fromMe = body?.data?.key?.fromMe ?? false;
const remoteJid = body?.data?.key?.remoteJid || '';
const messageId = body?.data?.key?.id || '';
const instance = body?.instance || body?.instanceName || '';

const msg = body?.data?.message || {};
const text = msg.conversation || msg.extendedTextMessage?.text || '';
const hasContent = !!(text || msg.audioMessage || msg.imageMessage);
const pushName = body?.data?.pushName || '';

const isMessage = evento.includes('messages');
const isGroup = remoteJid.endsWith('@g.us');

if (!isMessage || isGroup || !hasContent || (fromMe && !text.trim().startsWith('#'))) {
  return [];
}

return [{
  json: {
    instance: String(instance),
    remoteJid,
    telefone: remoteJid.replace(/@s\.whatsapp\.net$/, ''),
    text,
    pushName,
    fromMe,
    evento,
    messageId,
    body
  }
}];

const txt = v => (v == null || v === '') ? '' : String(v).trim();

let filtroData = {};
try { filtroData = $('Filtro + Extrair').first().json; } catch { filtroData = {}; }

const telefone = txt(filtroData.telefone);
const pushName = txt(filtroData.pushName);
const fromMe = filtroData.fromMe ?? false;
const instanciaWebhook = txt(filtroData.instance);
const text = txt(filtroData.text);
const messageId = txt(filtroData.messageId);

let rawNegocio = [];
try { rawNegocio = $('Carregar Dados Negócio').all().map(i => i.json); } catch { rawNegocio = []; }

if (rawNegocio.length === 0) {
  return [{ json: { erro: 'Negócio não encontrado.', instancia_recebida: instanciaWebhook } }];
}

const n = rawNegocio[0];
const inst = instanciaWebhook || txt(n.instancia_whatsapp);

let servicosLista = 'Consultar catálogo.';
try {
  const raw = n.servicos_json || '';
  if (raw && raw !== '[]') {
    let s = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (Array.isArray(s) && s.length > 0) {
      servicosLista = s.map(x => `- ${x.nome || 'Produto'}: R$ ${x.preco || 'consulte'}${x.duracao ? ' (' + x.duracao + ' min)' : ''}`).join('\n');
    }
  }
} catch { if (n.servicos_json) servicosLista = n.servicos_json; }

return [{ json: {
  instancia: inst,
  cliente_id: n.cliente_id ?? n.id ?? null,
  session_id: `${inst}_${telefone}`,
  nome_empresa: txt(n.nome_empresa) || 'Empresa',
  nome_proprietario: txt(n.nome_proprietario),
  telefone_empresa: txt(n.telefone),
  endereco: txt(n.endereco),
  horario_funcionamento: txt(n.horario_funcionamento) || 'Horário comercial',
  formas_pagamento: txt(n.formas_pagamento) || 'Consulte',
  informacoes_extras: txt(n.informacoes_extras),
  nome_atendente_ia: txt(n.nome_atendente_ia) || 'Assistente de Vendas',
  tom_voz: txt(n.tom_voz) || 'Consultiva, calorosa e persuasiva',
  servicos_lista: servicosLista,
  telefone, pushName, fromMe, text, messageId,
  telefone_proprietario: txt(n.telefone),
  remoteJid: telefone + '@s.whatsapp.net',
  default_calendar: txt(n.default_calendar),
  evo_api_url: txt(n.evo_api_url) || 'https://evo.upviaagentes.com',
  evo_api_key: txt(n.evo_api_key) || '3gl0eq56t0ahsh3m5lx7ruv8i764qcvd',
  catalogo_sheets_id: txt(n.catalogo_sheets_id),
  link_vendas: txt(n.link_vendas),
  tipo_produto: txt(n.tipo_produto)
} }];

let items = [];
try { items = $('Carregar Catálogo Sheets').all().map(i => i.json); } catch { items = []; }

let catalogo = '';
if (items.length > 0) {
  catalogo = items.map((p, i) => {
    const nome = p.nome || p.produto || p.Produto || 'Produto';
    const preco = p.preco || p.valor || p.Preço || 'Consulte';
    const desc = p.descricao || p.Descrição || '';
    const beneficio = p.beneficio || p.Benefício || '';
    const categoria = p.categoria || p.Categoria || '';
    const estoque = p.estoque || p.Estoque || '';
    const upsell = p.upsell || p.Upsell || '';
    return `[${i+1}] ${nome} — R$ ${preco}${desc ? ' | ' + desc : ''}${beneficio ? ' | Benefício: ' + beneficio : ''}${categoria ? ' | Cat: ' + categoria : ''}${upsell ? ' | Combina com: ' + upsell : ''}${estoque ? ' | Estoque: ' + estoque : ''}`;
  }).join('\n');
} else {
  catalogo = $('Montar Contexto Dinâmico').first().json.servicos_lista || 'Catálogo indisponível no momento.';
}

const ctx = $('Montar Contexto Dinâmico').first().json;

return [{ json: { ...ctx, catalogo } }];

