CREATE TABLE IF NOT EXISTS carrinho_abandonado (
  id bigserial PRIMARY KEY,
  telefone text NOT NULL,
  session_id text,
  instancia text NOT NULL,
  ultima_msg text,
  status text DEFAULT 'ativo',
  followup_1h boolean DEFAULT false,
  followup_6h boolean DEFAULT false,
  followup_24h boolean DEFAULT false,
  created_at timestamptz DEFAULT NOW(),
  updated_at timestamptz DEFAULT NOW(),
  UNIQUE(telefone, instancia)
);

ALTER TABLE dados_cliente ADD COLUMN IF NOT EXISTS recuperado boolean DEFAULT false;
ALTER TABLE dados_cliente ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT NOW();
ALTER TABLE clientes_sistema ADD COLUMN IF NOT EXISTS catalogo_sheets_id text;
ALTER TABLE clientes_sistema ADD COLUMN IF NOT EXISTS link_vendas text;
ALTER TABLE clientes_sistema ADD COLUMN IF NOT EXISTS tipo_produto text DEFAULT 'fisico';
